import React from 'react';
import { Container } from 'react-bootstrap';

const Footer = () => {
  return (
    <footer className="bg-dark text-white text-center py-3">
      <Container>
        <p>© 2025 FI Money. All rights reserved.</p>
      </Container>
    </footer>
  );
};

export default Footer;
